import pandas as pd
import numpy as np

def generate_signals(df: pd.DataFrame) -> pd.Series:
    # Calculate the Stochastic %K(28)
    n = 28
    df['HH'] = df['high'].rolling(window=n).max()
    df['LL'] = df['low'].rolling(window=n).min()
    df['%K'] = 100 * (df['close'] - df['LL']) / (df['HH'] - df['LL'])

    # Initialize the position series with 0
    positions = pd.Series(0, index=df.index)

    # Warm-up period
    warm_up_period = n - 1
    positions.iloc[:warm_up_period] = 0

    # Generate signals
    for i in range(warm_up_period, len(df)):
        if positions.iloc[i-1] == 0:
            if df['%K'].iloc[i] < 20:
                positions.iloc[i] = 1
            elif df['%K'].iloc[i] > 80:
                positions.iloc[i] = -1
        elif positions.iloc[i-1] == 1:
            if df['%K'].iloc[i] > 45:
                positions.iloc[i] = 0
        elif positions.iloc[i-1] == -1:
            if df['%K'].iloc[i] < 45:
                positions.iloc[i] = 0

    return positions
