def generate_signals(df: pd.DataFrame) -> pd.Series:
    # Calculate RSI(16)
    delta = df['close'].diff()
    gain = (delta.where(delta > 0, 0)).rolling(window=16).mean()
    loss = (-delta.where(delta < 0, 0)).rolling(window=16).mean()
    rs = gain / loss
    rsi = 100 - (100 / (1 + rs))

    # Initialize positions
    positions = pd.Series(0, index=df.index)

    # Warm-up period
    warm_up_period = 16
    positions[warm_up_period:] = 0

    # Generate signals
    for i in range(warm_up_period, len(df)):
        if positions[i-1] == 0:
            if rsi[i] < 28:
                positions[i] = 1
            elif rsi[i] > 72:
                positions[i] = -1
        elif positions[i-1] == 1:
            if rsi[i] > 52:
                positions[i] = 0
        elif positions[i-1] == -1:
            if rsi[i] < 52:
                positions[i] = 0

    return positions
