    # Initialize the position series with 0
    signals = pd.Series(0, index=df.index)

    # Iterate over the DataFrame to determine the signals
    for i in range(n, len(df)):
        if signals[i-1] == 0:
            if rsi[i] < 35:
                signals[i] = 1
            elif rsi[i] > 65:
                signals[i] = -1
        elif signals[i-1] == 1:
            if rsi[i] > 52:
                signals[i] = 0
        elif signals[i-1] == -1:
            if rsi[i] < 52:
                signals[i] = 0

