def generate_signals(df: pd.DataFrame) -> pd.Series:
    # Initialize the position series with zeros
    positions = pd.Series(0, index=df.index)

    # Calculate the 12-bar SMA and STD
    sma_12 = df['close'].rolling(window=12).mean()
    std_12 = df['close'].rolling(window=12).std(ddof=1)

    # Iterate over the DataFrame to determine positions
    for i in range(12, len(df)):
        close = df['close'][i]
        sma = sma_12[i]
        std = std_12[i]

        if positions[i-1] == 0:
            if close < sma - 1.25 * std:
                positions[i] = 1
            elif close > sma + 1.25 * std:
                positions[i] = -1
        elif positions[i-1] == 1:
            if close >= sma - 1 * std:
                positions[i] = 0
        elif positions[i-1] == -1:
            if close <= sma + 1 * std:
                positions[i] = 0

    return positions
