import numpy as np
import pandas as pd

def generate_signals(df: pd.DataFrame) -> pd.Series:
    # Calculate the 20-day simple moving average
    sma_20 = df['close'].rolling(window=20).mean()

    # Initialize the position series with 0s
    positions = pd.Series(0, index=df.index)

    # Initialize variables to track the entry price and position
    entry_price = None
    position = 0

    # Iterate over the DataFrame to determine positions
    for i in range(1, len(df)):
        if pd.isna(sma_20[i]):
            continue  # Skip warm-up period

        if position == 0:
            # Look for entry signals
            if df['close'][i] > sma_20[i] and df['close'][i-1] <= sma_20[i-1]:
                position = 1  # Go long
                entry_price = df['close'][i]
            elif df['close'][i] < sma_20[i] and df['close'][i-1] >= sma_20[i-1]:
                position = -1  # Go short
                entry_price = df['close'][i]
        else:
            # Look for exit signals
            if position == 1:
                if df['close'][i] <= entry_price * (1 - 0.04):
                    position = 0  # Stop-loss
                elif df['close'][i] >= entry_price * (1 + 0.08):
                    position = 0  # Take-profit
            elif position == -1:
                if df['close'][i] >= entry_price * (1 + 0.04):
                    position = 0  # Stop-loss
                elif df['close'][i] <= entry_price * (1 - 0.08):
                    position = 0  # Take-profit

        # Update the positions series
        positions[i] = position

    return positions
