import numpy as np
import pandas as pd

def generate_signals(df: pd.DataFrame) -> pd.Series:
    # Calculate SMA and PSTD
    sma_25 = df['close'].rolling(window=25).mean()
    pstd_25 = df['close'].rolling(window=25).std(ddof=0)

    # Calculate Bollinger Bands
    upper_band = sma_25 + 2.25 * pstd_25
    lower_band = sma_25 - 2.25 * pstd_25

    # Initialize the position series with 0s
    positions = pd.Series(0, index=df.index)

    # Iterate over the DataFrame to determine positions
    for i in range(25, len(df)):
        if positions[i-1] == 0:
            if df['close'][i] > upper_band[i]:
                positions[i] = 1
            elif df['close'][i] < lower_band[i]:
                positions[i] = -1
        elif positions[i-1] == 1:
            if df['close'][i] <= sma_25[i]:
                positions[i] = 0
        elif positions[i-1] == -1:
            if df['close'][i] >= sma_25[i]:
                positions[i] = 0

    return positions
