import pandas as pd
import numpy as np

def generate_signals(df: pd.DataFrame) -> pd.Series:
    signals = pd.Series(0, index=df.index)
    peak = pd.Series(np.nan, index=df.index)
    stop = pd.Series(np.nan, index=df.index)

    for t in range(12, len(df)):
        if np.isnan(peak[t-1]):
            peak[t] = df['close'][t-12:t].max()
            stop[t] = peak[t] * 0.9
        else:
            peak[t] = max(peak[t-1], df['close'][t])
            stop[t] = peak[t] * 0.9

        if signals[t-1] == 0:
            if df['close'][t] > peak[t-1]:
                signals[t] = 1
        elif signals[t-1] == 1:
            if df['close'][t] < stop[t]:
                signals[t] = 0

    return signals
